const startItem = `-- name: StartItem :execrows
UPDATE remediation_items SET outcome_revision = outcome_revision + 1, state = 'working', attempt = attempt + 1,
  reason = '', not_before = NULL, lease_worker = $2, lease_until = $3, change_id=$4, run_id = $5, updated_at = $6
WHERE id=$1
`

type StartItemParams struct {
	ID          ids.ID
	LeaseWorker string
	LeaseUntil  sql.NullTime
	ChangeID    ids.ID
	RunID       ids.ID
	UpdatedAt   time.Time
}

func (q *Queries) StartItem(ctx context.Context, arg StartItemParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, startItem,
		arg.ID,
		arg.LeaseWorker,
		arg.LeaseUntil,
		arg.ChangeID,
		arg.RunID,
		arg.UpdatedAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const stickItem = `-- name: StickItem :execrows
UPDATE remediation_items SET outcome_revision = outcome_revision + 1, state = 'stuck', reason = $2,
  lease_worker = '', lease_until = NULL, updated_at = $3
WHERE id=$1
`

type StickItemParams struct {
	ID        ids.ID
	Reason    string
	UpdatedAt time.Time
}

func (q *Queries) StickItem(ctx context.Context, arg StickItemParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, stickItem, arg.ID, arg.Reason, arg.UpdatedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertPool = `-- name: UpsertPool :exec
INSERT INTO worker_pools (kind, count, updated_at) VALUES ($1, $2, $3)
ON CONFLICT (kind) DO UPDATE SET count = excluded.count, updated_at = excluded.updated_at
`

type UpsertPoolParams struct {
	Kind      string
	Count     int64
	UpdatedAt time.Time
}

func (q *Queries) UpsertPool(ctx context.Context, arg UpsertPoolParams) error {
	_, err := q.db.ExecContext(ctx, upsertPool, arg.Kind, arg.Count, arg.UpdatedAt)
	return err
}
